<?php
session_start();

$routerHost = '192.168.0.1:8443';
$verifyTls = false;
$timeoutSec = 10;
$sampleDelayUs = 1000000;
$routerUser = (string)($_SESSION['router_user'] ?? '');
$routerPass = (string)($_SESSION['router_pass'] ?? '');
if ($routerUser === '' || $routerPass === '') { header('Location: index.php'); exit; }

function h(?string $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function formatBitsPerSecond(float $b, int $p=2): string { $u=['bps','Kbps','Mbps','Gbps','Tbps'];$b=max(0,$b);$n=$b>0?floor(log($b,1000)):0;$n=min($n,count($u)-1);return round($b/(1000**$n),$p).' '.$u[$n]; }
function routerosRequest($host,$user,$pass,$verify,$timeout,$path,$method='GET',?array $payload=null): array {
    $ch=curl_init('https://'.$host.'/rest'.$path);
    curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>strtoupper($method),CURLOPT_USERPWD=>$user.':'.$pass,CURLOPT_HTTPAUTH=>CURLAUTH_BASIC,CURLOPT_TIMEOUT=>$timeout,CURLOPT_CONNECTTIMEOUT=>$timeout,CURLOPT_HTTPHEADER=>['Content-Type: application/json']]);
    if(!$verify){curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,false);curl_setopt($ch,CURLOPT_SSL_VERIFYHOST,false);}
    if($payload!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($payload,JSON_UNESCAPED_SLASHES));
    $response=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);
    if($response===false)throw new RuntimeException('cURL error: '.$err);
    $decoded=json_decode($response,true);
    if($code>=400)throw new RuntimeException('RouterOS HTTP '.$code.': '.(is_array($decoded)?json_encode($decoded,JSON_UNESCAPED_SLASHES):$response));
    return is_array($decoded)?$decoded:[];
}
function fetchConnections($h,$u,$p,$v,$t): array { return routerosRequest($h,$u,$p,$v,$t,'/ip/firewall/connection/print','POST',['.proplist'=>'.id,protocol,src-address,dst-address,src-port,dst-port,reply-src-address,reply-dst-address,reply-src-port,reply-dst-port,orig-bytes,repl-bytes,tcp-state,timeout,srcnat,dstnat']); }
function connectionKey(array $r): string { return (string)($r['.id']??implode('|',[$r['protocol']??'',$r['src-address']??'',$r['src-port']??'',$r['dst-address']??'',$r['dst-port']??''])); }
function sampleHost($h,$u,$p,$v,$t,$delay,string $ip): array {
    $a=fetchConnections($h,$u,$p,$v,$t);$start=microtime(true);usleep($delay);$b=fetchConnections($h,$u,$p,$v,$t);$seconds=max(microtime(true)-$start,.001);$first=[];foreach($a as $r)$first[connectionKey($r)]=$r;$rows=[];$downTotal=0.0;$upTotal=0.0;
    foreach($b as $r){$key=connectionKey($r);if(!isset($first[$key]))continue;$old=$first[$key];$orig=max(0,(float)($r['orig-bytes']??0)-(float)($old['orig-bytes']??0))*8/$seconds;$repl=max(0,(float)($r['repl-bytes']??0)-(float)($old['repl-bytes']??0))*8/$seconds;$src=(string)($r['src-address']??'');$dst=(string)($r['dst-address']??'');$replyDst=(string)($r['reply-dst-address']??'');$localPort='';$remote='';$remotePort='';$up=0.0;$down=0.0;$direction='';
        if($src===$ip){$direction='outbound';$remote=$dst;$localPort=(string)($r['src-port']??'');$remotePort=(string)($r['dst-port']??'');$up=$orig;$down=$repl;}
        elseif($dst===$ip){$direction='inbound';$remote=$src;$localPort=(string)($r['dst-port']??'');$remotePort=(string)($r['src-port']??'');$up=$repl;$down=$orig;}
        elseif($replyDst===$ip){$direction='inbound';$remote=$src;$localPort=(string)($r['reply-dst-port']??'');$remotePort=(string)($r['src-port']??'');$up=$repl;$down=$orig;}
        else continue;
        $downTotal+=$down;$upTotal+=$up;$rows[]=['key'=>$key,'direction'=>$direction,'protocol'=>(string)($r['protocol']??''),'remote_ip'=>$remote,'local_port'=>$localPort,'remote_port'=>$remotePort,'download_bps'=>$down,'upload_bps'=>$up,'download_text'=>formatBitsPerSecond($down),'upload_text'=>formatBitsPerSecond($up),'tcp_state'=>(string)($r['tcp-state']??''),'timeout'=>(string)($r['timeout']??'')];
    }
    usort($rows,fn($x,$y)=>(($y['download_bps']+$y['upload_bps'])<=>($x['download_bps']+$x['upload_bps'])));
    return ['ok'=>true,'refreshedAt'=>date('Y-m-d H:i:s'),'sampleSeconds'=>$seconds,'download_bps'=>$downTotal,'upload_bps'=>$upTotal,'download_text'=>formatBitsPerSecond($downTotal),'upload_text'=>formatBitsPerSecond($upTotal),'connections'=>$rows];
}
$ip=trim((string)($_GET['ip']??''));$iface=trim((string)($_GET['iface']??''));$ajax=($_GET['ajax']??'')==='1';$data=null;$error=null;
try{if(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)===false)throw new RuntimeException('Invalid or missing host IP.');$data=sampleHost($routerHost,$routerUser,$routerPass,$verifyTls,$timeoutSec,$sampleDelayUs,$ip);}catch(Throwable $e){$error=$e->getMessage();}
if($ajax){header('Content-Type: application/json; charset=utf-8',true,$error?500:200);echo json_encode($error?['ok'=>false,'error'=>$error]:$data,JSON_UNESCAPED_SLASHES);exit;}
$back=$iface!==''?'interface.php?iface='.rawurlencode($iface):'index.php';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Host <?=h($ip)?> Traffic</title><style>:root{--bg:#0f172a;--panel:#111827;--panel2:#1f2937;--text:#e5e7eb;--muted:#94a3b8;--line:#334155;--green:#22c55e;--red:#ef4444;--accent:#38bdf8}*{box-sizing:border-box}body{margin:0;font:14px Arial,sans-serif;background:var(--bg);color:var(--text)}.wrap{width:min(1700px,calc(100% - 32px));margin:24px auto}.topbar{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.card{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:14px;padding:18px;margin-top:20px}h1,h2{margin:0}h2{font-size:18px;margin-bottom:14px}.muted{color:var(--muted)}.small{font-size:12px}.mono{font-family:Consolas,monospace}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.stat{border:1px solid #33415580;border-radius:10px;padding:12px}.label{color:var(--muted);font-size:12px}.value{font-size:18px;font-weight:700;margin-top:5px}.graph{width:100%;height:220px;background:#0f172a88;border:1px solid #33415580;border-radius:8px;margin-top:15px}.rx{color:#86efac}.tx{color:#fca5a5}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:1100px}th,td{padding:9px 10px;border-bottom:1px solid #33415580;text-align:left;white-space:nowrap}th{color:#cbd5e1;background:#ffffff08;position:sticky;top:0}.error{background:#7f1d1d55;padding:15px;border-radius:10px}a{color:var(--accent)}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}}</style></head><body><div class="wrap"><div class="topbar"><div><h1>Host: <?=h($ip)?></h1><div class="muted small">Live traffic since this page was opened · <span id="when"></span></div></div><a href="<?=h($back)?>">Back to interface</a></div><?php if($error):?><div class="card error"><?=h($error)?></div><?php else:?><section class="card"><h2>Host Traffic</h2><div class="stats"><div class="stat"><div class="label">Download</div><div class="value rx" id="down">—</div></div><div class="stat"><div class="label">Upload</div><div class="value tx" id="up">—</div></div><div class="stat"><div class="label">Viewed Download</div><div class="value" id="downTotal">0 B</div></div><div class="stat"><div class="label">Viewed Upload</div><div class="value" id="upTotal">0 B</div></div><div class="stat"><div class="label">Connections Seen</div><div class="value" id="seenCount">0</div></div></div><canvas id="graph" class="graph" width="1600" height="220"></canvas></section><section class="card"><h2>Inbound Connections / History</h2><div class="muted small" style="margin-bottom:12px">Connections initiated toward this host. Once traffic has been transferred while this page is open, the row remains listed.</div><div class="table-wrap"><table><thead><tr><th>Protocol</th><th>Remote IP</th><th>Local Port</th><th>Remote Port</th><th>Download</th><th>Upload</th><th>Viewed Download</th><th>Viewed Upload</th><th>State</th><th>Last Traffic</th></tr></thead><tbody id="inboundBody"></tbody></table></div></section><section class="card"><h2>Outbound Connections / History</h2><div class="muted small" style="margin-bottom:12px">Connections initiated by this host. Once traffic has been transferred while this page is open, the row remains listed.</div><div class="table-wrap"><table><thead><tr><th>Protocol</th><th>Remote IP</th><th>Local Port</th><th>Remote Port</th><th>Download</th><th>Upload</th><th>Viewed Download</th><th>Viewed Upload</th><th>State</th><th>Last Traffic</th></tr></thead><tbody id="outboundBody"></tbody></table></div></section><?php endif;?></div><script>window.__initial=<?=json_encode($data,JSON_UNESCAPED_SLASHES)?>;(function(){const $=id=>document.getElementById(id),hist=[],rows=new Map(),maxPts=120;let last=performance.now(),downBytes=0,upBytes=0,polling=false;function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}function bytes(n){const u=['B','KB','MB','GB','TB'];let i=0;n=Math.max(0,n);while(n>=1024&&i<u.length-1){n/=1024;i++}return n.toFixed(i?2:0)+' '+u[i]}function draw(){const c=$('graph');if(!c||!hist.length)return;const x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);let m=1;hist.forEach(p=>m=Math.max(m,p.d,p.u));function line(k,col){x.beginPath();x.strokeStyle=col;x.lineWidth=2;hist.forEach((p,i)=>{const px=(i/Math.max(1,maxPts-1))*w,py=h-(p[k]/m)*(h-8)-4;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}line('d','#22c55e');line('u','#ef4444')}function rowHtml(r){return '<tr><td>'+esc(r.protocol)+'</td><td class="mono">'+esc(r.remote_ip)+'</td><td>'+esc(r.local_port||'—')+'</td><td>'+esc(r.remote_port||'—')+'</td><td class="rx">'+esc(r.download_text)+'</td><td class="tx">'+esc(r.upload_text)+'</td><td>'+bytes(r.download_total)+'</td><td>'+bytes(r.upload_total)+'</td><td>'+esc(r.tcp_state||'—')+'</td><td>'+esc(r.last_traffic||'—')+'</td></tr>'}function render(d,initial=false){if(!d)return;const now=performance.now(),elapsed=initial?0:Math.max(.001,(now-last)/1000);last=now;$('when').textContent=d.refreshedAt||'';$('down').textContent=d.download_text||'—';$('up').textContent=d.upload_text||'—';if(!initial){downBytes+=Number(d.download_bps||0)*elapsed/8;upBytes+=Number(d.upload_bps||0)*elapsed/8}$('downTotal').textContent=bytes(downBytes);$('upTotal').textContent=bytes(upBytes);(d.connections||[]).forEach(r=>{let old=rows.get(r.key)||{...r,download_total:0,upload_total:0,last_traffic:'',seen:false};const moving=Number(r.download_bps||0)>0||Number(r.upload_bps||0)>0;if(!initial){old.download_total+=Number(r.download_bps||0)*elapsed/8;old.upload_total+=Number(r.upload_bps||0)*elapsed/8}if(moving){old.seen=true;old.last_traffic=new Date().toLocaleTimeString()}Object.assign(old,r);rows.set(r.key,old)});const shown=[...rows.values()].filter(r=>r.seen||r.download_total>0||r.upload_total>0);shown.sort((a,b)=>(b.download_bps+b.upload_bps)-(a.download_bps+a.upload_bps));const inbound=shown.filter(r=>r.direction==='inbound'),outbound=shown.filter(r=>r.direction==='outbound');$('seenCount').textContent=shown.length;$('inboundBody').innerHTML=inbound.map(rowHtml).join('');$('outboundBody').innerHTML=outbound.map(rowHtml).join('');hist.push({d:Number(d.download_bps||0),u:Number(d.upload_bps||0)});if(hist.length>maxPts)hist.shift();draw()}async function poll(){if(polling)return;polling=true;try{const u=new URL(location.href);u.searchParams.set('ajax','1');u.searchParams.set('t',Date.now());const r=await fetch(u,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Update failed');render(d)}catch(e){console.error(e)}finally{polling=false}}render(window.__initial,true);setInterval(poll,3000)})();</script></body></html>